    return { profile: null };
  }

  const fallback = (): SessionProfileResult => ({
    profile: handle ? { handle } : null,
  });
  if (!oauth.restore) return fallback();

  try {
    const session = await oauth.restore(did, false);
    if (session.did !== did) return { profile: null };
    let pdsOrigin: string | null = null;
    if (session.getTokenInfo) {
      const info = await session.getTokenInfo(false);
      if (info.sub !== did) return { profile: null };
      pdsOrigin = publicPdsOrigin(info.aud);
    }
    const publicProjection = (
      displayName: string | null,
      avatar?: AvatarBlob,
    ): PublicProfile | undefined =>
      pdsOrigin
        ? {
            did,
            displayName,
            handle,
            avatarUrl: avatar
              ? `${pdsOrigin}/xrpc/com.atproto.sync.getBlob?${new URLSearchParams({ did, cid: avatar.cid })}`
              : null,
          }
        : undefined;
    const signal = AbortSignal.timeout(3_000);
    const [repoResponse, recordResponse] = await Promise.all([
      session.fetchHandler(
        `/xrpc/com.atproto.repo.describeRepo?repo=${encodeURIComponent(did)}`,
        { signal, redirect: "error" },
      ),
      session.fetchHandler(
        `/xrpc/com.atproto.repo.getRecord?repo=${encodeURIComponent(did)}&collection=app.bsky.actor.profile&rkey=self`,
        { signal, redirect: "error" },
      ),
    ]);
    if (repoResponse.ok) {
      const repo = object(await repoResponse.json());
      if (repo?.did !== did) return { profile: null };
      handle = publicText(repo.handle) ?? handle;
    }
    if (!recordResponse.ok) {
      const error = await recordResponse.json().catch(() => null);
      const absent =
        recordResponse.status === 404 ||
        object(error)?.error === "RecordNotFound";
      const publicProfile =
        absent && repoResponse.ok ? publicProjection(null) : undefined;
      return { ...fallback(), ...(publicProfile ? { publicProfile } : {}) };
    }
    const record = object(await recordResponse.json());
    const value = object(record?.value);
    if (
      record?.uri !== `at://${did}/app.bsky.actor.profile/self` ||
      value?.$type !== "app.bsky.actor.profile"
    )
      return { profile: null };
    const displayName = publicText(value.displayName);
    const avatar = avatarBlob(value.avatar);
    const publicProfile = publicProjection(displayName, avatar);
    return {
      ...(publicProfile ? { publicProfile } : {}),
      profile:
        displayName || handle || avatar
          ? {
              displayName,
              handle,
              // The CSP permits self-hosted images. The route verifies this CID against
              // the current authenticated profile before reading the blob from its PDS.
              avatarUrl: avatar
                ? `/api/session/avatar?cid=${encodeURIComponent(avatar.cid)}`
                : null,
            }
          : null,
      ...(avatar ? { avatar, oauthSession: session } : {}),
    };
  } catch {
    // Missing/expired OAuth or absent profiles must not sign the user out.
    return fallback();
  }
}

export async function readSessionAvatar(
  result: SessionProfileResult,
  requestedCid: string,
): Promise<Response | null> {
  if (
    !result.oauthSession ||
    !result.avatar ||
    requestedCid !== result.avatar.cid
  )
    return null;
  try {
    const response = await result.oauthSession.fetchHandler(
      `/xrpc/com.atproto.sync.getBlob?did=${encodeURIComponent(result.oauthSession.did)}&cid=${encodeURIComponent(result.avatar.cid)}`,
      { signal: AbortSignal.timeout(3_000), redirect: "error" },
    );
    if (
      !response.ok ||
      response.headers
        .get("content-type")
        ?.split(";")[0]
        ?.trim()
        .toLowerCase() !== result.avatar.mimeType
    )
      return null;
    if (!response.body) return null;
    const reader = response.body.getReader();
    const chunks: Uint8Array[] = [];
    let size = 0;
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > MAX_AVATAR_BYTES || size > result.avatar.size) {
          await reader.cancel();
          return null;
        }
        chunks.push(value);
      }
    } finally {
      reader.releaseLock();
    }
    if (size !== result.avatar.size) return null;
    const body = new Uint8Array(size);
    let offset = 0;
    for (const chunk of chunks) {
      body.set(chunk, offset);
      offset += chunk.byteLength;
    }
    return new Response(body, {
      headers: {
        "Content-Type": result.avatar.mimeType,
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch {
    return null;
  }
}
import { v, type Infer } from "convex/values";

/** Only public identity metadata. No OAuth credentials or email belong here. */
export const publicProfileValidator = v.object({
  did: v.string(),
  displayName: v.union(v.string(), v.null()),
  handle: v.union(v.string(), v.null()),
  avatarUrl: v.union(v.string(), v.null()),
});
export type PublicProfile = Infer<typeof publicProfileValidator>;

function object(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

export function publicPdsOrigin(value: unknown): string | null {
  if (typeof value !== "string" || value.length > 2048) return null;
  try {
    const url = new URL(value);
    return url.protocol === "https:" &&
      !url.username &&
      !url.password &&
      url.pathname === "/" &&
      !url.search &&
      !url.hash
      ? url.origin
      : null;
  } catch {
    return null;
  }
}

function publicText(value: unknown): string | null | undefined {
  if (value === null) return null;
  if (typeof value !== "string") return undefined;
  const text = value.trim();
  if (
    text.length > 256 ||
    /[^\s<>()@]+@[^\s<>()@]+/.test(text) ||
    Array.from(text).some(
      (char) => char.charCodeAt(0) < 32 || char.charCodeAt(0) === 127,
    )
  )
    return undefined;
  return text || null;
}

/**
 * Both approval and gateway reads bind the projection to the stored OAuth
 * subject/resource. Parsing stays server-side; only whitelisted fields leave.
 */
export function publicProfileForSession(
  profile: unknown,
  did: string,
  sessionJson: string,
): Omit<PublicProfile, "did"> | null {
  const value = object(profile);
  if (!value || value.did !== did) return null;
  let tokenSet: Record<string, unknown> | null;
  try {
    tokenSet = object(object(JSON.parse(sessionJson))?.tokenSet);
  } catch {
    return null;
  }
  if (tokenSet?.sub !== did) return null;
  const pdsOrigin = publicPdsOrigin(tokenSet.aud);
  if (!pdsOrigin) return null;
  const displayName = publicText(value.displayName);
  const handle = publicText(value.handle);
  if (displayName === undefined || handle === undefined) return null;
  let avatarUrl: string | null = null;
  if (value.avatarUrl !== null) {
    if (typeof value.avatarUrl !== "string" || value.avatarUrl.length > 2048)
      return null;
    try {
      const url = new URL(value.avatarUrl);
      if (
        url.origin !== pdsOrigin ||
        url.username ||
        url.password ||
        url.hash ||
        url.pathname !== "/xrpc/com.atproto.sync.getBlob" ||
        [...url.searchParams].length !== 2 ||
        url.searchParams.get("did") !== did ||
        !/^[a-zA-Z0-9]{20,200}$/.test(url.searchParams.get("cid") ?? "")
      )
        return null;
      avatarUrl = url.href;
    } catch {
      return null;
    }
  }
  return { displayName, handle, avatarUrl };
}

