/** Public account identity, kept separate from the private contact address. */
export interface AccountIdentity {
  name?: string | null;
  handle?: string | null;
  image?: string | null;
  email?: string | null;
}

export interface AccountProfile {
  displayName?: string | null;
  handle?: string | null;
  avatarUrl?: string | null;
}

export function accountName(
  value: string | null | undefined,
): string | undefined {
  const name = value?.trim();
  // Old sessions may have an email in the name field. Never expose that as
  // a label, tooltip, accessible name, initial, or collaborator identity.
  if (!name || /\S+@\S+/.test(name) || name.startsWith("did:"))
    return undefined;
  return name;
}

export function accountAvatarUrl(
  value: string | null | undefined,
): string | undefined {
  const url = value?.trim();
  if (!url || /[\\\s]/.test(url)) return undefined;
  if (url.startsWith("/") && !url.startsWith("//")) return url;
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "https:" || parsed.username || parsed.password)
      return undefined;
    return url;
  } catch {
    return undefined;
  }
}

export function accountDisplayName(
  user: AccountIdentity | null | undefined,
  profile?: AccountProfile | null,
): string {
  return (
    accountName(profile?.displayName) ||
    accountName(user?.name) ||
    accountName(profile?.handle) ||
    accountName(user?.handle) ||
    "Writer"
  );
}

export function accountInitials(name: string): string {
  const safeName = accountName(name);
  if (!safeName) return "W";
  const words = safeName.split(/\s+/);
  return (
    Array.from(words[0])[0] +
    (words.length > 1 ? Array.from(words[words.length - 1])[0] : "")
  ).toLocaleUpperCase();
}

/** Merge only authenticated profile fields; email stays available privately. */
export function withAccountProfile<T extends AccountIdentity>(
  user: T,
  profile: AccountProfile | null,
): T & { name: string; image: string | undefined; handle: string | undefined } {
  return {
    ...user,
    name: accountDisplayName(user, profile),
    image: accountAvatarUrl(profile?.avatarUrl) || accountAvatarUrl(user.image),
    handle: accountName(profile?.handle) || accountName(user.handle),
  };
}
/**
 * Browser half of "Continue with Not Organic" — the only Twyne sign-in.
 *
 * PKCE against id.notorganic.info. The browser only keeps the verifier and
 * state; the code is redeemed by Convex (`/sign-in/notorganic`), which verifies
 * the DID and issues the Twyne session.
 */
export const NOTORGANIC_SIGN_IN_ATTEMPT = "twyne:notorganic-sign-in";
export const NOTORGANIC_CALLBACK_PATH = "/auth/notorganic/";

export interface NotOrganicSignInAttempt {
  state: string;
  verifier: string;
  expiresAt: number;
  origin: string;
  /** Where to land after the session is issued. Same-origin path only. */
  returnTo: string;
}

const encode = (bytes: Uint8Array) =>
  btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");

function safeReturnTo(value: string | undefined): string {
  if (
    typeof value !== "string" ||
    !value.startsWith("/") ||
    value.startsWith("//") ||
    value.includes("\\") ||
    [...value].some((character) => {
      const code = character.charCodeAt(0);
      return code < 32 || code === 127;
    })
  )
    return "/";
  return value;
}

export async function beginNotOrganicSignIn(
  origin: string,
  returnTo?: string,
): Promise<{ attempt: NotOrganicSignInAttempt; url: string }> {
  const verifier = encode(crypto.getRandomValues(new Uint8Array(32)));
  const state = encode(crypto.getRandomValues(new Uint8Array(32)));
  const challenge = encode(
    new Uint8Array(
      await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier)),
    ),
  );
  const url = new URL("https://id.notorganic.info/authorize");
  url.search = new URLSearchParams({
    response_type: "code",
    client_id: origin,
    redirect_uri: `${origin}${NOTORGANIC_CALLBACK_PATH}`,
    code_challenge_method: "S256",
    code_challenge: challenge,
    state,
    scope: "wallet:read",
    product: "twyne",
  }).toString();
  return {
    attempt: {
      state,
      verifier,
      expiresAt: Date.now() + 600_000,
      origin,
      returnTo: safeReturnTo(returnTo),
    },
    url: url.href,
  };
}

export function readNotOrganicCallback(
  attempt: NotOrganicSignInAttempt,
  url: URL,
): { code: string; verifier: string } {
  if (
    !attempt ||
    typeof attempt.state !== "string" ||
    !attempt.state ||
    typeof attempt.verifier !== "string" ||
    !/^[A-Za-z0-9._~-]{43,128}$/.test(attempt.verifier) ||
    !Number.isFinite(attempt.expiresAt) ||
    Date.now() >= attempt.expiresAt ||
    url.origin !== attempt.origin ||
    url.pathname !== NOTORGANIC_CALLBACK_PATH ||
    url.hash ||
    url.searchParams.has("error") ||
    url.searchParams.getAll("state").length !== 1 ||
    url.searchParams.get("state") !== attempt.state ||
    url.searchParams.getAll("code").length !== 1 ||
    !url.searchParams.get("code")
  ) {
    throw new Error(
      "This sign-in attempt expired or belongs to another tab. Please sign in again.",
    );
  }
  return { code: url.searchParams.get("code")!, verifier: attempt.verifier };
