  displayName?: string | null;
  handle?: string | null;
  avatarUrl?: string | null;
}

export function accountName(
  value: string | null | undefined,
): string | undefined {
  const name = value?.trim();
  // Old sessions may have an email in the name field. Never expose that as
  // a label, tooltip, accessible name, initial, or collaborator identity.
  if (!name || /\S+@\S+/.test(name) || name.startsWith("did:"))
    return undefined;
  return name;
}

export function accountAvatarUrl(
  value: string | null | undefined,
): string | undefined {
  const url = value?.trim();
  if (!url || /[\\\s]/.test(url)) return undefined;
  if (url.startsWith("/") && !url.startsWith("//")) return url;
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "https:" || parsed.username || parsed.password)
      return undefined;
    return url;
  } catch {
    return undefined;
  }
}

export function accountDisplayName(
  user: AccountIdentity | null | undefined,
  profile?: AccountProfile | null,
): string {
  return (
    accountName(profile?.displayName) ||
    accountName(user?.name) ||
    accountName(profile?.handle) ||
    accountName(user?.handle) ||
    "Writer"
  );
}

export function accountInitials(name: string): string {
  const safeName = accountName(name);
  if (!safeName) return "W";
  const words = safeName.split(/\s+/);
  return (
    Array.from(words[0])[0] +
    (words.length > 1 ? Array.from(words[words.length - 1])[0] : "")
  ).toLocaleUpperCase();
}

/** Merge only authenticated profile fields; email stays available privately. */
export function withAccountProfile<T extends AccountIdentity>(
  user: T,
  profile: AccountProfile | null,
): T & { name: string; image: string | undefined; handle: string | undefined } {
  return {
    ...user,
    name: accountDisplayName(user, profile),
    image: accountAvatarUrl(profile?.avatarUrl) || accountAvatarUrl(user.image),
    handle: accountName(profile?.handle) || accountName(user.handle),
  };
}
/**
 * Browser half of "Continue with Not Organic" — the only Twyne sign-in.
 *
 * PKCE against id.notorganic.info. The browser only keeps the verifier and
 * state; the code is redeemed by Convex (`/sign-in/notorganic`), which verifies
 * the DID and issues the Twyne session.
 */
export const NOTORGANIC_SIGN_IN_ATTEMPT = "twyne:notorganic-sign-in";
export const NOTORGANIC_CALLBACK_PATH = "/auth/notorganic/";

export interface NotOrganicSignInAttempt {
  state: string;
  verifier: string;
  expiresAt: number;
  origin: string;
  /** Where to land after the session is issued. Same-origin path only. */
  returnTo: string;
}

const encode = (bytes: Uint8Array) =>
  btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");

function safeReturnTo(value: string | undefined): string {
  if (
    typeof value !== "string" ||
    !value.startsWith("/") ||
    value.startsWith("//") ||
    value.includes("\\") ||
    [...value].some((character) => {
      const code = character.charCodeAt(0);
      return code < 32 || code === 127;
    })
  )
    return "/";
  return value;
}

export async function beginNotOrganicSignIn(
  origin: string,
  returnTo?: string,
): Promise<{ attempt: NotOrganicSignInAttempt; url: string }> {
  const verifier = encode(crypto.getRandomValues(new Uint8Array(32)));
  const state = encode(crypto.getRandomValues(new Uint8Array(32)));
  const challenge = encode(
    new Uint8Array(
      await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier)),
    ),
  );
  const url = new URL("https://id.notorganic.info/authorize");
  url.search = new URLSearchParams({
    response_type: "code",
    client_id: origin,
    redirect_uri: `${origin}${NOTORGANIC_CALLBACK_PATH}`,
    code_challenge_method: "S256",
    code_challenge: challenge,
    state,
    scope: "wallet:read",
    product: "twyne",
  }).toString();
  return {
    attempt: {
      state,
      verifier,
      expiresAt: Date.now() + 600_000,
      origin,
      returnTo: safeReturnTo(returnTo),
    },
    url: url.href,
  };
}

export function readNotOrganicCallback(
  attempt: NotOrganicSignInAttempt,
  url: URL,
): { code: string; verifier: string } {
  if (
    !attempt ||
    typeof attempt.state !== "string" ||
    !attempt.state ||
    typeof attempt.verifier !== "string" ||
    !/^[A-Za-z0-9._~-]{43,128}$/.test(attempt.verifier) ||
    !Number.isFinite(attempt.expiresAt) ||
    Date.now() >= attempt.expiresAt ||
    url.origin !== attempt.origin ||
    url.pathname !== NOTORGANIC_CALLBACK_PATH ||
    url.hash ||
    url.searchParams.has("error") ||
    url.searchParams.getAll("state").length !== 1 ||
    url.searchParams.get("state") !== attempt.state ||
    url.searchParams.getAll("code").length !== 1 ||
    !url.searchParams.get("code")
  ) {
    throw new Error(
      "This sign-in attempt expired or belongs to another tab. Please sign in again.",
    );
  }
  return { code: url.searchParams.get("code")!, verifier: attempt.verifier };
}

/** Redirect to Not Organic. Resolves only if the redirect could not start. */
export async function startNotOrganicSignIn(returnTo?: string): Promise<void> {
  const { attempt, url } = await beginNotOrganicSignIn(
    location.origin,
    returnTo ?? location.pathname + location.search,
  );
  sessionStorage.setItem(NOTORGANIC_SIGN_IN_ATTEMPT, JSON.stringify(attempt));
  location.assign(url);
}

/** Finish the redirect on the callback page; returns where to go next. */
export async function completeNotOrganicSignIn(
  url: URL,
  dependencies: {
    storage?: Pick<Storage, "getItem" | "removeItem">;
    client?: {
      $fetch: (
        path: string,
        options: {
          method: "POST";
          body: { code: string; verifier: string; origin: string };
        },
      ) => Promise<{ data?: unknown; error?: unknown }>;
      getSession: (options: {
        query: { disableCookieCache: true };
      }) => Promise<{ data?: unknown; error?: unknown }>;
    };
  } = {},
): Promise<string> {
  const storage = dependencies.storage ?? sessionStorage;
  const saved = storage.getItem(NOTORGANIC_SIGN_IN_ATTEMPT);
  storage.removeItem(NOTORGANIC_SIGN_IN_ATTEMPT);
  if (!saved) throw new Error("Start signing in again from Twyne.");
  let attempt: NotOrganicSignInAttempt;
  try {
    attempt = JSON.parse(saved) as NotOrganicSignInAttempt;
  } catch {
    throw new Error("Start signing in again from Twyne.");
  }
  const args = readNotOrganicCallback(attempt, url);
  const client =
    dependencies.client ?? (await import("./auth-client")).authClient;
  const result = await client.$fetch("/sign-in/notorganic", {
    method: "POST",
    body: { ...args, origin: attempt.origin },
  });
  if (result?.error) {
    throw new Error("Not Organic could not verify this sign-in.");
  }
  // The crossDomain client stores the new session cookie; refresh the atom.
  const refreshed = await client.getSession({
    query: { disableCookieCache: true },
  });
  const issuedUser = record(record(result?.data)?.user);
  const sessionData = record(refreshed?.data);
  const session = record(sessionData?.session);
  const user = record(sessionData?.user);
  if (
    refreshed?.error ||
    typeof issuedUser?.id !== "string" ||
    !issuedUser.id ||
    !session ||
    typeof session.id !== "string" ||
    !session.id ||
    session.userId !== issuedUser.id ||
    user?.id !== issuedUser.id
  ) {
    throw new Error(
      "Twyne could not confirm your session. Please sign in again.",
    );
  }
  return safeReturnTo(attempt.returnTo);
}

function record(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}
import { createDpopKeyPair, createDpopFetch } from "./notorganic";

/** Redeem a one-time provider authorization; no caller-supplied DID is trusted. */
export async function redeemProviderLink(
  input: { code: string; verifier: string },
  siteUrl: string,
  issuer: string,
  fetchImpl: typeof fetch = fetch,
  redirectPath = "/settings/",
): Promise<{ did: string; sessionVersion: number; handle?: string }> {
  if (
    !input.code ||
    input.code.length > 2048 ||
    !/^[A-Za-z0-9._~-]{43,128}$/.test(input.verifier)
  ) {
    throw new Error(
      "The connection attempt is invalid. Start again from Settings.",
    );
  }
  const origin = new URL(siteUrl).origin;
  const dpop = await createDpopKeyPair();
  const response = await fetchImpl(`${issuer}/v1/public/token`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    signal: AbortSignal.timeout(15_000),
    body: JSON.stringify({
      code: input.code,
      code_verifier: input.verifier,
      client_id: origin,
      redirect_uri: `${origin}${redirectPath}`,
      dpop_jwk: dpop.publicJwk,
    }),
  });
  if (!response.ok)
    throw new Error(
      "Not Organic could not verify this connection. Start again from Settings.",
    );
  const body = (await response.json()) as { access_token?: string };
  if (typeof body.access_token !== "string" || !body.access_token)
    throw new Error("Not Organic returned no account proof.");
  const accountResponse = await createDpopFetch(
    { accessToken: body.access_token, dpop },
    fetchImpl,
  )(`${issuer}/v1/account`, { signal: AbortSignal.timeout(15_000) });
  if (!accountResponse.ok)
    throw new Error("Not Organic could not verify account ownership.");
  const account = (await accountResponse.json()) as {
    account?: { did?: string; handle?: string | null };
  };
  // This token has now been authenticated by the issuer with its DPoP proof.
  const encoded = body.access_token.split(".")[1];
  const claims = JSON.parse(
    atob(encoded.replace(/-/g, "+").replace(/_/g, "/")),
  ) as { sub?: string; product?: string; session_version?: number };
  if (
    !account.account?.did ||
    !/^did:[a-z0-9]+:[A-Za-z0-9._:%-]+$/.test(account.account.did) ||
    account.account.did !== claims.sub ||
    claims.product !== "twyne" ||
    !Number.isSafeInteger(claims.session_version) ||
    claims.session_version! < 0
  ) {
    throw new Error(
      "The verified account does not match this Twyne connection.",
    );
  }
  const handle = account.account.handle;
  return {
    did: account.account.did,
    sessionVersion: claims.session_version!,
    ...(typeof handle === "string" && handle ? { handle } : {}),
  };
}

