+/** Explicit development approvals retain the exact scheme, host and port. */
+export function parsePublicClientProductCatalog(
+  configured: Record<string, string>,
+): Record<string, Product> {
+  return Object.fromEntries(Object.entries(configured).map(([clientId, product]) => {
+    let client: URL;
+    try {
+      client = new URL(clientId);
+    } catch (error) {
+      throw new Error(`PUBLIC_CLIENT_PRODUCT_CATALOG contains an invalid client id: ${clientId}`, { cause: error });
+    }
+    const loopback = client.protocol === "http:" &&
+      ["localhost", "127.0.0.1", "[::1]"].includes(client.hostname);
+    if (!(client.protocol === "https:" || loopback) || client.origin !== clientId || client.username || client.password || client.hostname.includes("*")) {
+      throw new Error(`PUBLIC_CLIENT_PRODUCT_CATALOG keys must be exact HTTPS or loopback HTTP origins: ${clientId}`);
+    }
+    return [clientId, parseProductId(product)];
+  }));
+}

