app.post("/v1/auth/token/exchange", async (c) => {
  const body = await c.req.json<{
    assertion?: unknown;
    dpop_jwk?: JWK;
    scope?: unknown;
  }>();
  if (typeof body.assertion !== "string") {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "assertion is required.",
      "missing_assertion",
      "assertion",
    );
  }
  return c.json(
    await tokens.exchange({
      assertion: body.assertion,
      dpopJwk: body.dpop_jwk,
      requestedScope: typeof body.scope === "string" ? body.scope : undefined,
    }),
  );
});

app.post("/v1/public/token", async (c) => {
  const body = await c.req.json<{
    code?: unknown;
    code_verifier?: unknown;
    client_id?: unknown;
    redirect_uri?: unknown;
    dpop_jwk?: JWK;
    device_session?: unknown;
    device_name?: unknown;
  }>();
  if (
    typeof body.code !== "string" ||
    typeof body.code_verifier !== "string" ||
    typeof body.client_id !== "string" ||
    typeof body.redirect_uri !== "string"
  )
    throw new GatewayError(
      400,
      "invalid_request_error",
      "code, code_verifier, client_id, and redirect_uri are required.",
      "invalid_public_token_request",
    );
  if (
    !/^[A-Za-z0-9._~-]{43,128}$/.test(body.code_verifier) ||
    body.code.length > 512 ||
    body.client_id.length > 2_048 ||
    body.redirect_uri.length > 2_048
  )
    throw new GatewayError(
      400,
      "invalid_request_error",
      "The public authorization parameters are malformed.",
      "invalid_public_token_request",
    );
  if (body.device_session !== undefined && body.device_session !== true)
    throw new GatewayError(
      400,
      "invalid_request_error",
      "device_session must be true when requested.",
      "invalid_device_session_request",
    );
  if (
    body.device_name !== undefined &&
    (typeof body.device_name !== "string" ||
      body.device_name.trim().length === 0 ||
      body.device_name.length > 120)
  )
    throw new GatewayError(
      400,
      "invalid_request_error",
      "device_name must be between 1 and 120 characters.",
      "invalid_device_name",
    );
  const codeHash = Buffer.from(
    await crypto.subtle.digest(
      "SHA-256",
      new TextEncoder().encode(body.code),
    ),
  ).toString("base64url");
  return c.json(
    await tokens.exchangePublicCode({
      codeHash,
      codeVerifier: body.code_verifier,
      clientId: body.client_id,
      redirectUri: body.redirect_uri,
      dpopJwk: body.dpop_jwk,
      createDeviceSession: body.device_session === true,
      deviceName:
        typeof body.device_name === "string"
          ? body.device_name.trim()
          : undefined,
    }),
    200,
    { "cache-control": "no-store", pragma: "no-cache" },
  );
});

