import { CapabilitySchema, type Capability } from "@notorganic/contracts";

/**
 * Self-hosted clients are deliberately dynamic public OAuth clients. There is
 * no shared secret or product signing key to steal: a client may only use its
 * own HTTPS origin and exact callback URL, and a user sees that origin before
 * approving narrowly-scoped access. Loopback is permitted for local desktop
 * development, but arbitrary custom schemes are not.
 */
export interface PublicAuthorizationRequest {
  clientId: string;
  redirectUri: string;
  codeChallenge: string;
  scope: string;
  state?: string;
  environment: "browser" | "mobile";
}

export const KEATING_MOBILE_CLIENT_ID = "https://keating.help/mobile";
export const KEATING_MOBILE_REDIRECT_URI = "keating:///notorganic/callback";

export const PUBLIC_CLIENT_CAPABILITIES = [
  "wallet:read",
  "usage:read",
  "billing:checkout",
  "infer:fast",
  "infer:balanced",
  "infer:reasoning",
  "infer:vision",
  "infer:embedding",
  "infer:image",
  "infer:audio",
  "judgement:evaluate",
  "realtime:connect",
] as const satisfies readonly Capability[];

export const KEATING_MOBILE_CAPABILITIES = [
  "wallet:read",
  "usage:read",
  "billing:checkout",
  "infer:balanced",
  "judgement:evaluate",
  "sync:key:read",
  "evolution:read",
  "evolution:write",
  "evolution:execute",
  "realtime:connect",
] as const satisfies readonly Capability[];

const CHALLENGE = /^[A-Za-z0-9_-]{43,128}$/;
const STATE = /^[A-Za-z0-9._~-]{0,1024}$/;

export function validatePublicAuthorization(input: Record<string, string | undefined>):
  | { ok: true; value: PublicAuthorizationRequest; scopes: readonly Capability[]; clientOrigin: string }
  | { ok: false; message: string } {
  if (input.response_type !== "code") return { ok: false, message: "Only response_type=code is supported." };
  if (input.code_challenge_method !== "S256") return { ok: false, message: "PKCE S256 is required." };
  if (!input.client_id || !input.redirect_uri || !input.code_challenge) return { ok: false, message: "client_id, redirect_uri, and code_challenge are required." };
  if (!CHALLENGE.test(input.code_challenge)) return { ok: false, message: "The PKCE code challenge is invalid." };
  if (input.state !== undefined && !STATE.test(input.state)) return { ok: false, message: "The state value is invalid." };
  let client: URL;
  let redirect: URL;
  try { client = new URL(input.client_id); redirect = new URL(input.redirect_uri); } catch { return { ok: false, message: "client_id and redirect_uri must be absolute URLs." }; }
