async getAccount(input: { accountId: string }): Promise<unknown> {
  return await this.convex.query(accountRef, {
    serviceSecret: this.config.gatewaySecret,
    did: input.accountId,
  });
}

async getWallet(input: {
  accountId: string;
  product?: Product;
}): Promise<unknown> {
  const welcomeCredit =
    (input.product === "keating" || input.product === "twyne")
      ? await this.convex.mutation(welcomeGrantRef, {
          serviceSecret: this.config.gatewaySecret,
          did: input.accountId,
          product: input.product,
        })
      : undefined;
  const wallet = await this.convex.query(walletRef, {
    serviceSecret: this.config.gatewaySecret,
    did: input.accountId,
    ...(input.product ? { product: input.product } : {}),
  });
  return { ...wallet, ...(welcomeCredit ? { welcomeCredit } : {}) };
}

