16: export const NOTORGANIC_PROVIDER_ID = "notorganic";
17: export const NOTORGANIC_SIGN_IN_PATH = "/auth/notorganic/";
18: 
19: export interface VerifiedNotOrganicAccount {
20:   did: string;
21:   sessionVersion: number;
22:   handle?: string;
23:   displayName?: string;
24:   /** Undefined leaves the stored avatar alone; null removes it. */
25:   avatarUrl?: string | null;
26: }
27: 
28: /** Preserve profile fields from the same DPoP-authenticated account proof. */
29: export async function redeemNotOrganicSignIn(
30:   input: { code: string; verifier: string },
31:   origin: string,
32:   issuer: string,
33:   fetchImpl: typeof fetch = fetch,
34: ): Promise<VerifiedNotOrganicAccount> {
35:   let account: Record<string, unknown> | null = null;
36:   const verified = await redeemProviderLink(
37:     input,
38:     origin,
39:     issuer,
40:     (async (input: RequestInfo | URL, init?: RequestInit) => {
41:       const response = await fetchImpl(input, init);
42:       const url = input instanceof Request ? input.url : String(input);
43:       if (url === `${issuer}/v1/account` && response.ok) {
44:         const body: unknown = await response.clone().json();
45:         if (body !== null && typeof body === "object" && "account" in body) {
46:           const value = body.account;
47:           if (
48:             value !== null &&
49:             typeof value === "object" &&
50:             !Array.isArray(value)
51:           ) {
52:             account = value as Record<string, unknown>;
53:           }
54:         }
55:       }
56:       return response;
57:     }) as typeof fetch,
58:     NOTORGANIC_SIGN_IN_PATH,
59:   );
60:   // redeemProviderLink already checked the account DID, token product and
61:   // session version. Optional profile data never establishes identity.
62:   const profile = account as Record<string, unknown> | null;
63:   const displayName =
64:     typeof profile?.displayName === "string"
65:       ? profile.displayName.trim().slice(0, 256)
66:       : undefined;
67:   const avatarUrl = safeAvatarUrl(profile?.avatarUrl);
68:   return {
69:     ...verified,
70:     ...(displayName ? { displayName } : {}),
71:     ...(avatarUrl !== undefined ? { avatarUrl } : {}),
72:   };
73: }
74: 
75: function safeAvatarUrl(value: unknown): string | null | undefined {
